package com.frezzamusic.app.ui
import androidx.compose.foundation.layout.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.*;import androidx.compose.ui.unit.dp
import androidx.media3.common.Player
import com.frezzamusic.app.model.Track;import com.frezzamusic.app.player.PlaybackController
@Composable fun FullPlayer(track:Track?,pc:PlaybackController,onClose:()->Unit){val p=pc.controller;var pos by remember{mutableFloatStateOf((p?.currentPosition?:0).toFloat())};val dur=(p?.duration?:0).coerceAtLeast(0);Column(Modifier.fillMaxSize().padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Row(Modifier.fillMaxWidth()){IconButton(onClose){Icon(Icons.Default.KeyboardArrowDown,null)};Spacer(Modifier.weight(1f));IconButton({pc.repeat()}){Icon(Icons.Default.Repeat,null)}};Spacer(Modifier.weight(1f));Icon(Icons.Default.Album,null,Modifier.size(180.dp),tint=MaterialTheme.colorScheme.primary);Spacer(Modifier.height(24.dp));Text(track?.title?:"Nada tocando",style=MaterialTheme.typography.headlineSmall);Text(track?.artist?:"");Slider(pos,{pos=it},onValueChangeFinished={pc.seek(pos.toLong())},valueRange=0f..dur.coerceAtLeast(1).toFloat());Row(verticalAlignment=Alignment.CenterVertically){IconButton({pc.shuffle()}){Icon(Icons.Default.Shuffle,null)};IconButton({pc.previous()}){Icon(Icons.Default.SkipPrevious,null)};FilledIconButton({pc.toggle()},Modifier.size(64.dp)){Icon(if(p?.isPlaying==true)Icons.Default.Pause else Icons.Default.PlayArrow,null)};IconButton({pc.next()}){Icon(Icons.Default.SkipNext,null)};IconButton({}){Icon(Icons.Default.Lyrics,null)}};Spacer(Modifier.weight(1f))}}
